import pandas as pd, numpy as np
# gather regen dose vs conversion from experiments
for eid in [1,2,3,4,6,7,8,9]:
    try:
        df=pd.read_csv(globals()[f"experiment_{eid}_csv"])
        cols=[c for c in df.columns]
        regcol=[c for c in cols if 'Regen' in c]
        convcol=[c for c in cols if 'Conversion' in c or 'Efficiency' in c]
        bpcol=[c for c in cols if 'Byproduct' in c]
        poison=[c for c in cols if 'Poison' in c]
        print(eid, "cols:", cols[:8])
        msg=[]
        if regcol: msg.append(f"regen={df[regcol[0]].mean():.1f}")
        if convcol: msg.append(f"conv={df[convcol[0]].mean():.2f}")
        if bpcol: msg.append(f"bp={df[bpcol[0]].mean():.2f}")
        if poison: msg.append(f"poison={df[poison[0]].mean():.2f}")
        print("   ", msg)
    except Exception as e:
        print(eid, "err", e)

